import { buildFixture } from '../../lib/career/fixtures'
import { completeRace } from '../../lib/career/model'

/** A real v4 win generated by the shared fixture engine, with a historical (unsettled) record. */
export function paidCareer() {
  const fixture = buildFixture('result-win')
  const { result } = fixture.log!
  const won = completeRace(
    fixture.career!,
    fixture.log!.raceRunId,
    result.placing,
    result.prizeMoney,
  )
  return {
    ...won,
    month: 6,
    careerTurnIndex: 6,
    calendarDate: { year: 2028, month: 9 },
    health: '정상',
    healthRecovery: 0,
    values: { ...won.values, fatigue: 5, bodyLoad: 5 },
  }
}
export const paidDraft = {
  raceId: 'DEV_M6_LISTED_2000',
  jockeyId: 'SEO_JIAN',
  tactic: '선입',
} as const
